                Object clobTokenId = (clobTokenIds == null || oi < 0 || oi >= ((List<?>)clobTokenIds).size() ? null : ((List<?>)clobTokenIds).get(oi));
                Double outcomePrice = this.safeNumber(outcomePrices, oi, (Object) null);
